        await typeCode(code);
        await narrate(`Welcome to the core mechanism that powers JavaScript's object-oriented nature: the prototype. Unlike classical inheritance, JavaScript uses <b>prototypal inheritance</b>: <i>objects inherit directly from other objects</i>.`);

        moveHighlight(2);
        await narrate(`<b>Part 1: The Foundation.</b> In JavaScript, every object has a hidden internal property, [[Prototype]], which is a link to another object.`);
        createObjectViz('v', 'vehicle', `<div class="property"><span class="key">isEnginePowered</span>: <span class="value">true</span></div><div class="property"><span class="key">start</span>: <span class="value">ƒ ()</span></div>`, prototypesContainer);

        moveHighlight(11);
        await narrate(`Let's build a prototype chain manually using <code>Object.create()</code>. We create 'car' and set its prototype to 'vehicle'.`);
        createObjectViz('c', 'car', ``, prototypesContainer);
        await animateArrow('c', 'v');

        moveHighlight(12);
        updateObjectViz('c', `<div class="property"><span class="key">wheelCount</span>: <span class="value">4</span></div><div class="property"><span class="key">drive</span>: <span class="value">ƒ ()</span></div>`);

        moveHighlight(19);
        await narrate(`Level 3: We create 'myTesla' and link it to 'car'. The chain ends when we reach an object whose [[Prototype]] is null.`);
        createObjectViz('t', 'myTesla', ``, instancesContainer);
        await animateArrow('t', 'c');

